    const typing = e.target.matches('textarea, input:not([type=radio]):not([type=checkbox]), select');
    if (!typing && (e.key === 'n' || e.key === 'p' || e.key === 'N' || e.key === 'P')) { e.preventDefault(); stepQuestion(e.key.toLowerCase() === 'n' ? 1 : -1, e.shiftKey); return; }
